ts_example:
// TypeScript: consumer using async iterator
import { createCompactStreamClient } from '@redwood/sdk';
const client = createCompactStreamClient({ compact: false });
for await (const evt of client.streamInvocation({ model: 'redwood-psi', prompt: 'calc 2+2' })) {
  if (evt.type === 'delta') process.stdout.write(evt.delta);
  if (evt.type === 'tool-call') console.log('Invoke tool', evt.tool);
  if (evt.type === 'tool-result') console.log('Tool result', evt.result);
}

py_example:
# Python: generator-based consumer
from redwood import CompactStreamClient
client = CompactStreamClient(compact=False)
for evt in client.stream_invocation({'model': 'redwood-psi', 'prompt': 'lookup weather'}):
    if evt['type'] == 'delta':
        print(evt['delta'], end='')
    elif evt['type'] == 'tool-call':
        handle_tool(evt['tool'])
    elif evt['type'] == 'done':
        break

go_example:
// Go: channel consumer
client := sdk.NewCompactClient(sdk.Config{Compact:false})
events := client.StreamInvocation(ctx, sdk.Request{Model:'redwood-psi', Prompt:'summarize report'})
for e := range events {
  switch e.Type {
  case sdk.EventDelta: fmt.Print(e.Delta)
  case sdk.EventToolCall: go runTool(e.Tool)
  case sdk.EventDone: return
  }
}
